/**
 * Fake axios. Called directly (downloads in PrinterService) every response is a small
 * PNG-like buffer; the test reads `__requests`. The instance methods (`get`, `patch`, `post`,
 * used by ApiService) go through `__handler({ method, url, data, config })` when a test sets
 * one, otherwise they reject. `create(config)` returns this same function and records the
 * config in `__createConfigs` so a test can check headers.
 */
const requests = [];
const createConfigs = [];
function axios(config) {
    requests.push(config);
    const data = Buffer.from('fake-png');
    return Promise.resolve({ data: config.responseType === 'stream' ? require('stream').Readable.from([data]) : data });
}
async function viaHandler(method, url, data, config) {
    const call = { method, url, data, config };
    requests.push(call);
    if (typeof axios.__handler !== 'function') {
        throw new Error(`axios stub: no __handler set for ${method.toUpperCase()} ${url}`);
    }
    return axios.__handler(call);
}
axios.get = (url, config) => viaHandler('get', url, undefined, config);
axios.delete = (url, config) => viaHandler('delete', url, undefined, config);
axios.post = (url, data, config) => viaHandler('post', url, data, config);
axios.patch = (url, data, config) => viaHandler('patch', url, data, config);
axios.put = (url, data, config) => viaHandler('put', url, data, config);
axios.create = (config) => {
    createConfigs.push(config || {});
    return axios;
};
axios.__handler = null;
axios.__requests = requests;
axios.__createConfigs = createConfigs;
module.exports = axios;
module.exports.default = axios;
